import json
from pathlib import Path
p=Path('scripts/jk-tilemap-20261111')
s='''if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!="Assets/Scenes/Level05_Cave.unity")UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level05_Cave.unity");var l=UnityEngine.Object.FindObjectOfType<CampaignLevel>();var death=UnityEngine.Object.FindObjectOfType<Character.Lifecycle.Death>();death.transform.parent.position+=(UnityEngine.Vector3)l.initialSpawn-death.transform.position;var v=UnityEditor.SceneView.lastActiveSceneView;v.in2DMode=true;v.LookAt(new UnityEngine.Vector3(12,3,0),UnityEngine.Quaternion.identity,10,true,true);v.Focus();v.Repaint();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());'''
(p/'frame.json').write_text(json.dumps(dict(name='exec_editor_script',arguments=dict(script=s,summary='Show saved fifth-level Tilemap and align edit-mode character preview with spawn'))))
s='''System.Collections.IEnumerator Capture(){yield return new UnityEngine.WaitForSeconds(1);if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Level05_Cave")throw new System.Exception("Wrong active scene");var m=UnityEngine.Object.FindObjectsOfType<UnityEngine.Tilemaps.Tilemap>().Single(m=>m.name.StartsWith("Jump King"));var col=m.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();var l=CampaignLevel.Current;var death=UnityEngine.Object.FindObjectOfType<Character.Lifecycle.Death>();var lines=new System.Collections.Generic.List<string>();lines.Add("Live scene="+UnityEngine.SceneManagement.SceneManager.GetActiveScene().name+"; spawn="+l.initialSpawn+"; body="+death.transform.position+"; dead="+death.Dead);int slopes=0,wrong=0;foreach(var pos in m.cellBounds.allPositionsWithin){var tile=m.GetTile(pos) as UnityEngine.Tilemaps.Tile;if(tile==null)continue;string n=UnityEditor.AssetDatabase.GetAssetPath(tile);int k=int.Parse(n.Substring(n.LastIndexOf("Slope")+5,1));var center=m.GetCellCenterWorld(pos);var inside=center+new UnityEngine.Vector3(k==1||k==3?-.4f/6:.4f/6,k==1||k==2?-.4f/6:.4f/6);var outside=center-(inside-center);if(!col.OverlapPoint(inside)||col.OverlapPoint(outside))wrong++;slopes++;}lines.Add("Exact triangle inside/outside tests="+slopes+"; mismatch="+wrong);if(wrong>0)throw new System.Exception("Slope classification mismatch");foreach(var c in UnityEngine.Object.FindObjectsOfType<Cinemachine.CinemachineVirtualCamera>())c.enabled=false;foreach(var rb in UnityEngine.Object.FindObjectsOfType<UnityEngine.Rigidbody2D>())if(rb.bodyType!=UnityEngine.RigidbodyType2D.Static)rb.simulated=false;var cam=UnityEngine.Camera.main;cam.orthographicSize=8;var centers=new[]{new UnityEngine.Vector2(12,3),new UnityEngine.Vector2(12,118),new UnityEngine.Vector2(12,239)};for(int i=0;i<centers.Length;i++){cam.transform.position=new UnityEngine.Vector3(centers[i].x,centers[i].y,-10);yield return null;yield return new UnityEngine.WaitForEndOfFrame();UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/jk-tilemap-20261111/play-"+i+".png"));yield return null;yield return new UnityEngine.WaitForEndOfFrame();}System.IO.File.WriteAllLines("scripts/jk-tilemap-20261111/play-verification.txt",lines);}return Capture();'''
(p/'capture.json').write_text(json.dumps(dict(name='exec_runtime_script',arguments=dict(script=s,summary='Check live spawn, exact slope collision, and capture actual Game regions without save resets'))))
